(()=>{
const root=document.createElement('aside');root.id='lumi-guide';root.className='lumi-guide pet-guide';root.setAttribute('aria-label','Lumi onboarding companion');
root.innerHTML=`<div class="lumi-speech" aria-live="polite"><span id="lumi-speech-line"></span></div><button class="assistant-dock" aria-label="Open QuoteLens assistant" aria-expanded="false" aria-controls="lumi-assistant">✧ <span>Assistant</span></button><section id="lumi-assistant" class="assistant-panel" hidden aria-label="QuoteLens assistant"><div class="assistant-head"><div><strong>QuoteLens assistant</strong><span>Guided preview · No live AI</span></div><button data-assistant-close aria-label="Close assistant">×</button></div><div class="assistant-thread" aria-live="polite"><p class="assistant-answer">Hi, I can guide you through the next step. Ask about your brief, suppliers, comparison or drafts.</p></div><form id="assistant-form"><label class="visually-hidden" for="assistant-question">Ask for help</label><input id="assistant-question" placeholder="What should I do next?" autocomplete="off" maxlength="200"><button type="submit" aria-label="Ask assistant">↗</button></form><small>Prepared guidance for this demo. No messages are sent.</small></section><section id="lumi-step-card" class="lumi-step-card" hidden aria-label="Your next step"><div class="pet-card-head"><span>LUMI’S LITTLE GUIDE</span><button data-lumi-close aria-label="Dismiss guide">×</button></div><div id="lumi-step-content"></div><div class="pet-card-actions"><button data-lumi-action class="button primary small">Show me</button><button data-lumi-hide class="text-link">I’ll explore</button></div><small>Guided tips · No live AI session</small></section><button class="lumi-pet-button" aria-expanded="false" aria-controls="lumi-step-card" aria-label="Lumi: show my next step"><span class="pet-spark">✦</span><span class="lumi-pet" aria-hidden="true"><i class="pet-ear left"></i><i class="pet-ear right"></i><i class="pet-tail"></i><span class="pet-body"><span class="pet-face"><i class="pet-eye"></i><i class="pet-eye"></i><i class="pet-nose"></i><i class="pet-blush left"></i><i class="pet-blush right"></i></span><i class="pet-paw left"></i><i class="pet-paw right"></i><span class="pet-badge">✦</span></span></span><span class="pet-name">Lumi <small>Your next step ↗</small></span></button>`;
document.body.append(root);const panel=root.querySelector('.lumi-step-card'),launch=root.querySelector('.lumi-pet-button'),content=root.querySelector('#lumi-step-content'),action=root.querySelector('[data-lumi-action]');let highlighted=null,current;const speech=root.querySelector('#lumi-speech-line'),assistant=root.querySelector('#lumi-assistant'),dock=root.querySelector('.assistant-dock');
const context=()=>window.getQuoteLensContext?.()||{view:'landing'};
function step(){const c=context();const steps={landing:{n:1,title:'Let’s start with your purchase.',text:'Open your workspace. Each tender keeps its own brief, supplier offers and decisions together.',label:'Open My Tenders',href:'app.html'},tenders:{n:1,title:'A little workspace for a big decision.',text:'Create a tender for your next purchase, or open an existing one to pick up where you left off.',label:'Show new tender',selector:'[data-action="new"]'},requirements:{n:1,title:'Start with your own words.',text:'What are you buying, who is it for, and what matters most? Add a budget, a date and your must-haves. The extra sections can wait.',label:'Show where to start',selector:'#brief-description'},quotations:{n:2,title:c.quotationCount?'Let’s get to know each supplier.':'Time to meet your suppliers.',text:c.quotationCount?'Add company names and whether you have worked together. Keep supplier history separate from the written offer.':'Choose the supplier PDFs. I’ll point you to a short form for the company name, contact and your previous experience.',label:'Show supplier quotations',selector:c.quotationCount?'.quote-list':'#dropzone'},comparison:{n:3,title:c.hasAssessment?'Look beyond the lowest price.':'Your comparison comes after the brief.',text:c.hasAssessment?'Select a price bar, then check the requirements below. Red means a mandatory mismatch; amber means a trade-off or something to clarify.':'Review your brief and supplier details first. Live evaluation is not connected in this preview.',label:c.hasAssessment?'Show the comparison':'Review quotations',selector:c.hasAssessment?'.visual-chart-panel':null,view:c.hasAssessment?null:'quotations'},evaluation:{n:3,title:'Follow the checks, one at a time.',text:'This page separates the sample replay from your actual saved actions. Check warnings before deciding what to do next.',label:'Show the activity',selector:'.activity-console'},drafts:{n:4,title:'A thoughtful next conversation.',text:'Open a supplier draft, check its recipient and requested changes, then edit it in your own voice. Nothing sends automatically.',label:'Show the drafts',selector:'.draft-hub'},suppliers:{n:1,title:'Get to know the people behind the offer.',text:'Explore a portfolio’s services, selected work and client remarks. Share a clear brief once you see a possible fit.',label:'Show me the portfolio',selector:'.portfolio-overview, .directory-grid'}};return steps[c.view]||steps.landing;}
function speak(){const c=context();const lines={landing:['Need suppliers? Start with their portfolios.','Already have quotes? Open your workspace.'],tenders:['One tender, one clear decision.','Shall we set up a new brief?'],requirements:['Tell me in your own words.','We can add the finer details later.'],quotations:['Who sent this offer?','A little company context helps.'],comparison:['The lowest price is not always the best fit.','Check the red mismatches first.'],evaluation:['Here is what happened, step by step.'],drafts:['Read it over before you send.'],suppliers:['Meet the people behind the proposal.','Look at their work and client remarks.']};const options=lines[c.view]||lines.landing,index=Number(speech.dataset.index||0)%options.length;speech.textContent=options[index];speech.dataset.index=String(index+1);speech.classList.remove('speech-appear');void speech.offsetWidth;speech.classList.add('speech-appear')}
function paint(){current=step();content.innerHTML=`<div class="pet-progress" aria-label="Step ${current.n} of 4">${[1,2,3,4].map(n=>`<span class="${n<=current.n?'done':''}"></span>`).join('')}</div><span class="pet-stage">${context().view==='suppliers'?'EXPLORE SUPPLIERS':`STEP ${current.n} · ${['START WITH A BRIEF','ADD YOUR OFFERS','UNDERSTAND THE FIT','TAKE THE NEXT STEP'][current.n-1]}`}</span><h3>${current.title}</h3><p>${current.text}</p>`;action.textContent=current.label;}
function clearHighlight(){highlighted?.classList.remove('lumi-spotlight');highlighted=null;}
function open(topic){paint();if(topic==='cost'&&context().hasAssessment){current={...current,title:'Is the extra ₹1,400 worth it?',text:'Print & Co. is ₹31,000 with its optional sample. Studio Merch is ₹32,400 and includes individual packaging. Both meet the essentials. If bulk packaging works for you, Print & Co. is the lower-cost fit.',label:'Show the price explanation',selector:'.selected-insight'};content.querySelector('h3').textContent=current.title;content.querySelector('p').textContent=current.text;action.textContent=current.label;}panel.hidden=false;launch.setAttribute('aria-expanded','true');}
function close(){panel.hidden=true;launch.setAttribute('aria-expanded','false');clearHighlight();launch.focus();try{sessionStorage.setItem('ql-lumi-onboarded','1')}catch{}}
launch.addEventListener('click',()=>{assistant.hidden=true;dock.setAttribute('aria-expanded','false');panel.hidden?open():close()});root.querySelector('[data-lumi-close]').addEventListener('click',close);root.querySelector('[data-lumi-hide]').addEventListener('click',close);
action.addEventListener('click',()=>{clearHighlight();if(current.href){location.href=current.href;return}if(current.view&&typeof go==='function'){go(current.view);open();return}const target=document.querySelector(current.selector||'.app-content');if(target){target.closest('details')?.setAttribute('open','');highlighted=target;target.classList.add('lumi-spotlight');target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});if(target.matches('input,textarea,button'))target.focus({preventScroll:true});setTimeout(clearHighlight,6500)}else{content.querySelector('p').textContent='This step is not ready yet. Complete the tender brief and add supplier quotations first.'}});
window.addEventListener('quotelens:view',()=>{clearHighlight();speak();if(!panel.hidden)paint()});document.addEventListener('click',e=>{const trigger=e.target.closest('[data-guide]');if(trigger)open(trigger.dataset.guide)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden)close()});
dock.addEventListener('click',()=>{assistant.hidden=!assistant.hidden;dock.setAttribute('aria-expanded',String(!assistant.hidden));if(!assistant.hidden){panel.hidden=true;launch.setAttribute('aria-expanded','false');assistant.querySelector('input').focus()}});root.querySelector('[data-assistant-close]').addEventListener('click',()=>{assistant.hidden=true;dock.setAttribute('aria-expanded','false');dock.focus()});root.querySelector('#assistant-form').addEventListener('submit',e=>{e.preventDefault();const input=e.currentTarget.querySelector('input'),q=input.value.trim();if(!q)return;const thread=root.querySelector('.assistant-thread'),user=document.createElement('p');user.className='assistant-question';user.textContent=q;thread.append(user);const answer=document.createElement('p');answer.className='assistant-answer';const v=q.toLowerCase();answer.textContent=/supplier|contractor|portfolio|find/.test(v)?'Explore supplier portfolios, projects and remarks. Share the quantity, date, location and must-haves when asking for a quotation.':/price|cost|compare|budget|cheapest/.test(v)?'Open Comparison and select a bar. Check mandatory mismatches before weighing the price difference.':/email|draft|send|reply/.test(v)?'Open Email drafts, review the recipient and requested changes, then edit the message. This preview does not send email.':/brief|requirement|tender/.test(v)?'Start with what you need, your budget ceiling, date and what absolutely cannot change. The extra questions are optional.':step().text;thread.append(answer);input.value='';thread.scrollTop=thread.scrollHeight});speak();setInterval(()=>{if(!document.hidden&&assistant.hidden&&panel.hidden)speak()},7000);
})();
